<?php
namespace App\Controllers;
use App\Core\{Controller,Database,Auth,Request,Response};
use App\Services\{AuditService,NumberService,ActivityService,EventService};
final class ServiceRequestController extends Controller {
    public function index(): void {if(!Auth::can('request.view')){$this->forbidden();return;}$db=Database::connection();$t=Auth::tenantId();$s=$db->prepare("SELECT sr.*,c.name customer_name,cs.site_name,ca.asset_code FROM service_requests sr JOIN customers c ON c.id=sr.customer_id AND c.tenant_id=sr.tenant_id LEFT JOIN customer_sites cs ON cs.id=sr.site_id AND cs.tenant_id=sr.tenant_id LEFT JOIN customer_assets ca ON ca.id=sr.asset_id AND ca.tenant_id=sr.tenant_id WHERE sr.tenant_id=? AND sr.deleted_at IS NULL ORDER BY sr.id DESC");$s->execute([$t]);$c=$db->prepare("SELECT id,name FROM customers WHERE tenant_id=? AND deleted_at IS NULL AND status='active' ORDER BY name");$c->execute([$t]);$sites=$db->prepare("SELECT id,customer_id,site_name FROM customer_sites WHERE tenant_id=? AND deleted_at IS NULL ORDER BY site_name");$sites->execute([$t]);$assets=$db->prepare("SELECT id,customer_id,asset_code,category FROM customer_assets WHERE tenant_id=? AND deleted_at IS NULL ORDER BY asset_code");$assets->execute([$t]);$this->view('requests/index',['title'=>'Service Requests','requests'=>$s->fetchAll(),'customers'=>$c->fetchAll(),'sites'=>$sites->fetchAll(),'assets'=>$assets->fetchAll()]);}
    public function store(): void {$this->requireCsrf();if(!Auth::can('request.create'))Response::json(['success'=>false,'message'=>'Forbidden','errors'=>[]],403);$t=(int)Auth::tenantId();$customer=(int)Request::input('customer_id');$problem=trim((string)Request::input('problem_description'));if(!$customer||$problem==='')Response::json(['success'=>false,'message'=>'Customer dan problem description wajib diisi.','errors'=>[]],422);$db=Database::connection();$num=NumberService::next($t,'service_request','SR');$priority=(string)Request::input('priority','Normal');$sla=$db->prepare("SELECT response_minutes,resolution_minutes FROM sla_policies WHERE tenant_id=? AND priority=? AND active=1 ORDER BY id LIMIT 1");$sla->execute([$t,$priority]);$policy=$sla->fetch();$response=$policy?date('Y-m-d H:i:s',time()+(int)$policy['response_minutes']*60):null;$resolution=$policy?date('Y-m-d H:i:s',time()+(int)$policy['resolution_minutes']*60):null;$db->prepare("INSERT INTO service_requests(tenant_id,request_number,request_date,customer_id,site_id,asset_id,service_category,problem_description,priority,requested_date,contact_person,status,response_deadline,resolution_deadline,created_by,created_at,updated_at) VALUES(?,?,CURDATE(),?,?,?,?,?,?,?,?, 'New',?,?,?,NOW(),NOW())")->execute([$t,$num,$customer,Request::input('site_id')?:null,Request::input('asset_id')?:null,Request::input('service_category'),$problem,$priority,Request::input('requested_date')?:null,Request::input('contact_person'),$response,$resolution,Auth::id()]);$id=(int)$db->lastInsertId();AuditService::log('create','service_request',$id,null,['request_number'=>$num]);$ce=$db->prepare("SELECT email FROM customers WHERE id=? AND tenant_id=?");$ce->execute([$customer,$t]);EventService::emit($t,'service_request.created',['request_number'=>$num,'request_id'=>$id,'priority'=>$priority],null,$ce->fetchColumn()?:null,'service_request_received');ActivityService::log('service_request',$id,'created','Service request received');Response::json(['success'=>true,'message'=>'Service request berhasil dibuat.','data'=>['reload'=>true]]);}
    public function status(string $id): void {$this->requireCsrf();if(!Auth::can('request.edit'))Response::json(['success'=>false,'message'=>'Forbidden','errors'=>[]],403);$allowed=['New','Reviewed','Need Survey','Quoted','Approved','Scheduled','Assigned','In Progress','On Hold','Completed','Cancelled','Closed'];$st=(string)Request::input('status');if(!in_array($st,$allowed,true))Response::json(['success'=>false,'message'=>'Status invalid.','errors'=>[]],422);Database::connection()->prepare("UPDATE service_requests SET status=?,updated_by=?,updated_at=NOW() WHERE id=? AND tenant_id=? AND deleted_at IS NULL")->execute([$st,Auth::id(),(int)$id,Auth::tenantId()]);Response::json(['success'=>true,'message'=>'Request status diperbarui.','data'=>['reload'=>true]]);}
    public function convert(string $id,string $target): void {$this->requireCsrf();$db=Database::connection();$t=(int)Auth::tenantId();$s=$db->prepare("SELECT * FROM service_requests WHERE id=? AND tenant_id=? AND deleted_at IS NULL");$s->execute([(int)$id,$t]);$r=$s->fetch();if(!$r)Response::json(['success'=>false,'message'=>'Request tidak ditemukan.','errors'=>[]],404);if($target==='survey'){$num=NumberService::next($t,'survey','SUR');$db->prepare("INSERT INTO surveys(tenant_id,survey_number,service_request_id,customer_id,site_id,surveyor_id,survey_date,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,CURDATE(),?,NOW(),NOW())")->execute([$t,$num,(int)$id,$r['customer_id'],$r['site_id'],Auth::id(),'Created from '.$r['request_number']]);$newId=(int)$db->lastInsertId();$status='Need Survey';$redirect='/surveys';$msg='Survey '.$num.' dibuat.';}elseif($target==='quotation'){$num=NumberService::next($t,'quotation','QUO');$db->prepare("INSERT INTO quotations(tenant_id,quotation_number,customer_id,quotation_date,valid_until,sales_user_id,status,notes,created_at,updated_at) VALUES(?,?,?,CURDATE(),DATE_ADD(CURDATE(),INTERVAL 14 DAY),?,'Draft',?,NOW(),NOW())")->execute([$t,$num,$r['customer_id'],Auth::id(),'Created from '.$r['request_number']]);$newId=(int)$db->lastInsertId();$status='Quoted';$redirect='/quotations/'.$newId;$msg='Quotation '.$num.' dibuat.';}elseif($target==='job'){$num=NumberService::next($t,'job','JOB');$db->prepare("INSERT INTO jobs(tenant_id,job_number,customer_id,site_id,asset_id,service_request_id,service_category,description,priority,scheduled_date,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,'Draft',?,NOW(),NOW())")->execute([$t,$num,$r['customer_id'],$r['site_id'],$r['asset_id'],(int)$id,$r['service_category'],$r['problem_description'],$r['priority'],$r['requested_date'],$r['created_by']?:Auth::id()]);$newId=(int)$db->lastInsertId();$status='Scheduled';$redirect='/jobs/'.$newId;$msg='Job '.$num.' dibuat.';}else Response::json(['success'=>false,'message'=>'Target conversion tidak valid.','errors'=>[]],422);$db->prepare("UPDATE service_requests SET status=?,updated_by=?,updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([$status,Auth::id(),(int)$id,$t]);Response::json(['success'=>true,'message'=>$msg,'data'=>['redirect'=>url($redirect)]]);}
    private function forbidden():void{http_response_code(403);require BASE_PATH.'/app/Views/errors/403.php';}
}
